        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        BigDecimal principal = new BigDecimal(reader.readLine().trim());
        BigDecimal rate = new BigDecimal(reader.readLine().trim());
        BigDecimal term = new BigDecimal(reader.readLine().trim());

        BigDecimal numerator = principal.multiply(rate).multiply(term);
        BigDecimal denominator = new BigDecimal("1200");
        BigDecimal interest = numerator.divide(denominator, 2, RoundingMode.HALF_UP);
        BigDecimal total = principal.add(interest);

        String formattedInterest = String.format(Locale.ROOT, "%010.2f", interest.abs());
        String formattedTotal = String.format(Locale.ROOT, "%010.2f", total.abs());

